import{_ as e,o as n,c as t,a2 as i}from"./chunks/framework.EUByU7Iq.js";const _=JSON.parse('{"title":"第三章 合同的效力","description":"","frontmatter":{"title":"第三章 合同的效力","date":"2021-02-16T00:00:00.000Z","categories":["法律","民法典"],"tags":["法律","民法典"]},"headers":[],"relativePath":"blogs/CC/diyifenbian：tongze（disanzhang：hetongdexiaoli）.md","filePath":"blogs/CC/第一分编：通则（第三章：合同的效力）.md"}'),s={name:"blogs/CC/diyifenbian：tongze（disanzhang：hetongdexiaoli）.md"};function r(o,a,l,d,h,p){return n(),t("div",null,[...a[0]||(a[0]=[i(`<h3 id="第五百零二条" tabindex="-1">第五百零二条 <a class="header-anchor" href="#第五百零二条" aria-label="Permalink to &quot;第五百零二条&quot;">​</a></h3><p>依法成立的合同，自成立时生效，但是法律另有规定或者当事人另有约定的除外。 依照法律、行政法规的规定，合同应当办理批准等手续的，依照其规定。未办理批准等手续影响合同生效的，不影响合同中履行报批等义务条款以及相关条款的效力。应当办理申请批准等手续的当事人未履行义务的，对方可以请求其承担违反该义务的责任。 依照法律、行政法规的规定，合同的变更、转让、解除等情形应当办理批准等手续的，适用前款规定。</p><h3 id="第五百零三条" tabindex="-1">第五百零三条 <a class="header-anchor" href="#第五百零三条" aria-label="Permalink to &quot;第五百零三条&quot;">​</a></h3><p>无权代理人以被代理人的名义订立合同，被代理人已经开始履行合同义务或者接受相对人履行的，视为对合同的追认。</p><h3 id="第五百零四条" tabindex="-1">第五百零四条 <a class="header-anchor" href="#第五百零四条" aria-label="Permalink to &quot;第五百零四条&quot;">​</a></h3><p>法人的法定代表人或者非法人组织的负责人超越权限订立的合同，除相对人知道或者应当知道其超越权限外，该代表行为有效，订立的合同对法人或者非法人组织发生效力。</p><h3 id="第五百零五条" tabindex="-1">第五百零五条 <a class="header-anchor" href="#第五百零五条" aria-label="Permalink to &quot;第五百零五条&quot;">​</a></h3><p>当事人超越经营范围订立的合同的效力，应当依照本法第一编第六章第三节和本编的有关规定确定，不得仅以超越经营范围确认合同无效。</p><h3 id="第五百零六条" tabindex="-1">第五百零六条 <a class="header-anchor" href="#第五百零六条" aria-label="Permalink to &quot;第五百零六条&quot;">​</a></h3><p>合同中的下列免责条款无效：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>（一）造成对方人身损害的；</span></span>
<span class="line"><span>（二）因故意或者重大过失造成对方财产损失的。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="第五百零七条" tabindex="-1">第五百零七条 <a class="header-anchor" href="#第五百零七条" aria-label="Permalink to &quot;第五百零七条&quot;">​</a></h3><p>合同不生效、无效、被撤销或者终止的，不影响合同中有关解决争议方法的条款的效力。</p><h3 id="第五百零八条" tabindex="-1">第五百零八条 <a class="header-anchor" href="#第五百零八条" aria-label="Permalink to &quot;第五百零八条&quot;">​</a></h3><p>本编对合同的效力没有规定的，适用本法第一编第六章的有关规定。</p>`,15)])])}const b=e(s,[["render",r]]);export{_ as __pageData,b as default};
